def hydrate_time(nanoseconds, tz=None):
    """
    Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if tz is not None:
            return Time(nanoseconds, tz)
        else:
            return Time(nanoseconds)
    except ValueError as e:
        raise ValueError("Invalid time value: " + str(e))
    except TypeError as e:
        raise TypeError("Invalid time value: " + str(e))

def dehydrate_point(value):
    """
    Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise ValueError("Invalid input type. Expected Point.")

    return {
        "x": value.x,
        "y": value.y
    }

def index(self, key):
    try:
        return self.keys.index(key)
    except ValueError:
        return -1

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.values())
    else:
        return [self[key] for key in keys]

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """

    # Initialize an empty dictionary to store the data
    data_dict = {}

    # If no keys are provided, include all values
    if not keys:
        for key, value in self.items():
            data_dict[key] = value
    # Otherwise, include only the specified values
    else:
        for key in keys:
            # Check if the key is an index
            if isinstance(key, int):
                # Check if the index is out of bounds
                if key < 0 or key >= len(self):
                    raise IndexError("Index out of bounds")
                # Insert the value at the specified index
                data_dict[key] = self[key]
            # Otherwise, the key is a field name
            else:
                # Check if the field name is in the record
                if key not in self:
                    data_dict[key] = None
                else:
                    data_dict[key] = self[key]

    return data_dict

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    data = self.pop(2)
    return int.from_bytes(data, byteorder='big', signed=False)

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding ties to even numbers.

    :param n: the number to round
    :return: the rounded number
    """
    if n % 1 == 0.5:
        return int(n) + (n < 0)
    else:
        return int(n + 0.5)

def deprecated(message):
    """
    Decorator for deprecating functions and methods.

    :param message: The message to display when the deprecated function or method is called.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            print(f"WARNING: {func.__name__} is deprecated. {message}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

