def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not seq:
        return []
    else:
        shuffled = []
        for i in range(len(seq)):
            shuffled.append(seq[i])
        random.seed(0)
        random.shuffle(shuffled)
        return shuffled

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    version_parts = s.split(".")
    version_numbers = []
    for part in version_parts:
        try:
            version_numbers.append(int(part))
        except ValueError:
            raise ValueError(f"Invalid version number: {part}")
    return tuple(version_numbers)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key(*args, **kwargs)
            if key not in cache:
                cache[key] = func(*args, **kwargs)
            return cache[key]
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = {}
        last_accessed = {}
        def wrapped_func(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                last_accessed[key] = timer()
            elif timer() - last_accessed[key] > ttl:
                cache[key] = func(*args, **kwargs)
                last_accessed[key] = timer()
            return cache[key]
        return wrapped_func
    return wrapper

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def wrapper(func):
        cache = {}
        def wrapped_func(*args):
            key = str(args) if typed else args
            if key not in cache:
                cache[key] = func(*args)
            return cache[key]
        return wrapped_func
    return wrapper

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if len(self.items) == 0:
        raise KeyError("popitem(): dictionary is empty")
    key, value = self.items.pop(0)
    return key, value

def setdefault(self, key, default=None):
    if key not in self:
        self[key] = default
    return self.get(key, default)

def get(self, key, default=None):
    if key in self:
        return self[key]
    else:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key(*args, **kwargs)
            with cache.lock(key, lock=lock):
                try:
                    return cache[key]
                except KeyError:
                    pass
            value = func(*args, **kwargs)
            cache[key] = value
            return value
        return wrapper
    return decorator

def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        return object.__providedBy__()
    except AttributeError:
        return None

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    if all:
        return [(name, getattr(self, name).__doc__) for name in dir(self) if not name.startswith("_")]
    else:
        return [(name, getattr(self, name).__doc__) for name in dir(self) if not name.startswith("_") and getattr(self, name).__doc__ is not None]

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    if all:
        return list(self.__dict__.keys())
    else:
        return [key for key, value in self.__dict__.items() if not key.startswith("_")]

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not isinstance(sequence, list):
        raise TypeError("sequence must be a list")

    if output is not None and not isinstance(output, list):
        raise TypeError("output must be a list")

    normalized_sequence = []
    for item in sequence:
        if isinstance(item, Declaration):
            normalized_sequence.append(item)
        elif isinstance(item, tuple):
            normalized_sequence.append(item)
        elif isinstance(item, Interface):
            normalized_sequence.append(item)
        else:
            raise ValueError("Invalid item in sequence")

    if output is not None:
        for item in output:
            if isinstance(item, Declaration):
                normalized_sequence.append(item)
            elif isinstance(item, tuple):
                normalized_sequence.append(item)
            elif isinstance(item, Interface):
                normalized_sequence.append(item)
            else:
                raise ValueError("Invalid item in output")

    return normalized_sequence

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    return not _c_optimizations_required()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if self.initial_value is not None:
        self.bins = [self.initial_value] * self.num_bins
    else:
        self.bins = self.make_bins()
    return self.bins

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True
    elif isinstance(seq, list):
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    elif isinstance(seq, Source):
        return False
    else:
        raise ValueError("Invalid input type")
    return False

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < 0 or coord >= len(self.histogram):
        return
    self.histogram[coord] += weight

    # Handle edge cases
    if coord == 0:
        self.histogram[coord] = max(self.histogram[coord], weight)
    elif coord == len(self.histogram) - 1:
        self.histogram[coord] = max(self.histogram[coord], weight)
    else:
        self.histogram[coord] = max(self.histogram[coord], weight, self.histogram[coord - 1], self.histogram[coord + 1])

    # Handle negative weights
    if weight < 0:
        self.histogram[coord] = max(self.histogram[coord], -weight)

    # Handle overflow
    if self.histogram[coord] > self.max_value:
        self.max_value = self.histogram[coord]
        self.max_index = coord

    # Handle underflow
    if self.histogram[coord] < self.min_value:
        self.min_value = self.histogram[coord]
        self.min_index = coord

    # Handle NaN
    if isnan(self.histogram[coord]):
        self.histogram[coord] = 0

    # Handle infinity
    if isinf(self.histogram[coord]):
        self.histogram[coord] = 0

    # Handle negative infinity
    if isinf(self.histogram[coord]):
        self.histogram[coord] = 0

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial observer schema from a Kubernetes resource manifest dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resource manifest
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer schema
    """
    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item, first_level=False) for item in value]
        else:
            observer_schema[key] = None

    if first_level:
        for identifying_field in ["apiVersion", "kind", "metadata"]:
            observer_schema[identifying_field] = manifest_dict[identifying_field]

    return observer_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is a valid OCFL object
    if not self.is_ocfl_object(path):
        return False

    # Check if OCFL object has required properties
    if not self.has_required_properties(path):
        return False

    # Check if OCFL object has valid content
    if not self.has_valid_content(path):
        return False

    # Check if OCFL object has valid structure
    if not self.has_valid_structure(path):
        return False

    # Check if OCFL object has valid relationships
    if not self.has_valid_relationships(path):
        return False

    # Check if OCFL object has valid metadata
    if not self.has_valid_metadata(path):
