def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A list of commands to run.
    :param args: A list of arguments to pass to the command(s).
    :param cwd: The working directory to run the command(s) in.
    :param verbose: Whether to print the command(s) and its output.
    :param hide_stderr: Whether to hide the error output of the command(s).
    :param env: A dictionary of environment variables to set before running the command(s).
    :return: The output of the command(s).
    """

    # Check if the input is valid
    if not isinstance(commands, list):
        raise ValueError("'commands' must be a list")
    if not isinstance(args, list):
        raise ValueError("'args' must be a list")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("'cwd' must be a string or None")
    if not isinstance(verbose, bool):
        raise ValueError("'verbose' must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("'hide_stderr' must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise ValueError("'env' must be a dictionary or None")

    # Set the working directory
    if cwd is not None:
        os.chdir(cwd)

    # Set the environment variables
    if env is not None:
        for key, value in env.items():
            os.environ[key] = value

    # Run the command(s)
    output = []
    for command in commands:
        if verbose:
            print(command)
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        if not hide_stderr:
            print(stderr.decode("utf-8"))
        output.append(stdout.decode("utf-8"))

    # Return the output
    return output

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        # Check if the path is a directory
        if not os.path.isdir(path):
            return "not a directory"

        # Check if the path contains a "0=*" Namaste file
        for file in os.listdir(path):
            if file.startswith("0="):
                return "root" if file.endswith("root.nt") else "object"

        # If no "0=*" Namaste file is found, check if the path contains an inventory file
        for file in os.listdir(path):
            if file.endswith(".nt"):
                return "file"

        # If no inventory file is found, return an error message
        return "not a valid OCFL directory"
    except Exception as e:
        return f"Error: {e}"

def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key, value = node
        if key.value in [x[0].value for x in result]:
            index = [x[0].value for x in result].index(key.value)
            result[index] = (key, deep_merge_nodes([result[index][1], value]))
        else:
            result.append((key, value))
    return result

