def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative")

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = "0" * (padding - len(result)) + result

    return result

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    new_dict = {}
    for key, value in item.items():
        if re.match(r'\*.cpp', key):
            new_key = re.sub(r'\*.cpp', r'^.*\.cpp$', key)
        else:
            new_key = key
        new_dict[new_key] = value
    return new_dict

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = sys.platform
    if platform == 'posix':
        return _split_posix(s)
    elif platform == 'win32':
        return _split_win32(s)
    else:
        raise ValueError(f'Invalid platform: {platform}')

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
    except ValueError:
        raise ValueError(f"Invalid frequency: {frequency}")

    if unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    else:
        raise ValueError(f"Invalid unit of time: {unit}")

    return None

