def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """
    Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """
    try:
        self.before_cut_chars = before
        self.after_cut_chars = after
    except ValueError as e:
        raise ValueError("Invalid delimiter bytes") from e

    if not self.before_cut_chars and not self.after_cut_chars:
        raise ValueError("At least one delimiter byte must be specified")

    if self.before_cut_chars and self.after_cut_chars:
        if self.before_cut_chars == self.after_cut_chars:
            raise ValueError("Before and after delimiters cannot be the same")

    if self.before_cut_chars:
        self.before_cut_chars = self.before_cut_chars.encode()

    if self.after_cut_chars:
        self.after_cut_chars = self.after_cut_chars.encode()

