    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        if response.status_code == 200:
            return response.headers.get('Content-Type')
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node.children:
        if child.tag in result:
            result[child.tag].append(child.text)
        else:
            result[child.tag] = [child.text]
    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        response = requests.get(f"https://webfinger.net/{handle}/.well-known/webfinger")
        if response.status_code == 200:
            return response.text
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """

    # Step 1: Retrieve the webfinger document
    try:
        response = requests.get(f"https://{handle}.diaspora.software/.well-known/webfinger")
    except requests.exceptions.RequestException as e:
        raise ValueError(f"Failed to retrieve webfinger document for handle {handle}: {e}")

    # Step 2: Parse the webfinger document
    try:
        data = response.json()
    except json.decoder.JSONDecodeError as e:
        raise ValueError(f"Failed to parse webfinger document for handle {handle}: {e}")

    # Step 3: Extract the Diaspora profile information
    try:
        profile = data["links"][0]["href"]
    except (KeyError, IndexError) as e:
        raise ValueError(f"Failed to extract Diaspora profile information from webfinger document for handle {handle}: {e}")

    # Step 4: Return the Diaspora profile information
    return profile

def retrieve_diaspora_host_meta(host):
    try:
        response = requests.get(f"{host}/.well-known/host-meta.json")
        response.raise_for_status()
        return XRD.from_json(response.json())
    except requests.exceptions.HTTPError as e:
        if e.response.status_code == 404:
            raise DiasporaHostNotFoundError(f"Host {host} not found")
        else:
            raise DiasporaHostMetaError(f"Error retrieving host-meta for {host}: {e}")
    except requests.exceptions.RequestException as e:
        raise DiasporaHostMetaError(f"Error retrieving host-meta for {host}: {e}")

def workspace_manager(cls):
    """Gets the workspace manager. """
    return cls.workspace_manager

def plugins_manager(cls):
    """Gets the plugin manager. """
    return cls._plugin_manager

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = {}
    for arg in self.args:
        if arg in self.deprecated_args:
            deprecated_args[arg] = self.deprecated_args[arg]
    return deprecated_args

def validate_arg_deprecation(cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check if any of the arguments in the cli_args are deprecated
    for arg in cli_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{DEPRECATED_ARGS[arg]}' instead.")

    # Check if any of the arguments in the answer_file_args are deprecated
    for arg in answer_file_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{DEPRECATED_ARGS[arg]}' instead.")

    # If any of the arguments are deprecated, raise a ValueError
    if any(arg in DEPRECATED_ARGS for arg in cli_args) or any(arg in DEPRECATED_ARGS for arg in answer_file_args):
        raise ValueError("The arguments provided are deprecated and cannot be used.")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than {self.length}")
    return args

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg not in self.available_choices:
            raise ValueError(f"Invalid choice: {arg}. Must be one of {self.available_choices}")
    return args

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < self.min_value or arg > self.max_value:
            raise ValueError(f"Invalid argument value: {arg}. Must be between {self.min_value} and {self.max_value}.")
    return True

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        extra_vars = []
    for var in extra_vars:
        if var not in vars_dict:
            vars_dict[var] = None
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Handle boolean arguments
    for arg in self.boolean_args:
        if arg in values_dict:
            values_dict[arg] = values_dict[arg].lower() == "true"

    # Handle integer arguments
    for arg in self.integer_args:
        if arg in values_dict:
            values_dict[arg] = int(values_dict[arg])

    # Handle float arguments
    for arg in self.float_args:
        if arg in values_dict:
            values_dict[arg] = float(values_dict[arg])

    # Handle list arguments
    for arg in self.list_args:
        if arg in values_dict:
            values_dict[arg] = values_dict[arg].split(",")

    # Handle dictionary arguments
    for arg in self.dict_args:
        if arg in values_dict:
            values_dict[arg] = json.loads(values_dict[arg])

    # Handle file arguments
    for arg in self.file_args:
        if arg in values_dict:
            values_dict[arg] = open(values_dict[arg], "r")

    # Handle directory arguments
    for arg in self.directory_args:
        if arg in values_dict:
            values_dict[arg] = os.path.abspath(values_dict[arg])

    # Handle command-specific arguments
    if parser_name == "main":
        # Handle --help argument
        if "--help" in values_dict:
            values_dict["--help"] = True

        # Handle --version argument
        if "--version" in values_dict:
            values_dict["--version"] = True

    # Handle virsh arguments
    elif parser_name == "virsh":
        # Handle --connect argument
        if "--connect" in values_dict:
            values_dict["--connect"] = values_dict["--connect"].split(",")

        # Handle --secret argument
        if "--secret" in values_dict:
            values_dict["--secret"] = values_dict["--secret"].split(",")

    # Handle ospd arguments
    elif parser_name == "ospd":
        # Handle --config argument
        if "--config" in values_dict:
            values_dict["--config"] = values_dict["--config"].split(",")

        # Handle --secret argument
        if "--secret" in values_dict:
            values_dict["--secret"] = values_dict["--secret"].split(",")

    # Handle other arguments
    else:
        # Handle --help argument
        if "--help" in values_dict:
            values_dict["--help"] = True

        # Handle --version argument
        if "--version" in values_dict:
            values_dict["--version"] = True

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    with open(plugin_dir / "plugin.yaml", "r") as f:
        plugin_spec = yaml.safe_load(f)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value
    return flatten_dict
